sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;

    // Validate required fields
    if (!body.order_number) {
        response.setStatus(400);
        response.setBody({ error: 'order_number is required' });
        return;
    }
    if (!body.complaint_type) {
        response.setStatus(400);
        response.setBody({ error: 'complaint_type is required' });
        return;
    }

    var validTypes = ['missing_items', 'wrong_items', 'damaged_items', 'quality_issue', 'overcharge', 'partner_behavior', 'app_technical', 'other', 'late_delivery'];
    if (validTypes.indexOf(body.complaint_type) === -1) {
        response.setStatus(400);
        response.setBody({ error: 'Invalid complaint_type. Valid values: ' + validTypes.join(', ') });
        return;
    }

    var utils = new x_2145749_qc.VaAgentUtils();
    var result = utils.createComplaintCase({
        orderNumber: body.order_number,
        complaintType: body.complaint_type,
        description: body.description || '',
        orderValue: body.order_value || null,
        isEscalated: body.is_escalated || false,
        userId: body.user_id || gs.getUserID()
    });

    if (result.success) {
        response.setStatus(201);
    } else {
        response.setStatus(500);
    }
    response.setBody({ result: result });
})(request, response)
